import{_ as a,o as t,c as l,a2 as o}from"./chunks/framework.BZO4qERu.js";const h=JSON.parse('{"title":"Ajax","description":"","frontmatter":{},"headers":[],"relativePath":"frontend/ajax.md","filePath":"frontend/ajax.md","lastUpdated":1781086744000}'),i={name:"frontend/ajax.md"};function r(d,e,s,n,c,p){return t(),l("div",null,[...e[0]||(e[0]=[o('<h1 id="ajax" tabindex="-1">Ajax <a class="header-anchor" href="#ajax" aria-label="Permalink to &quot;Ajax&quot;">​</a></h1><p>Ajax(Asynchronous Javascript and XML) 异步Javascript和XML，主要作用是使客户端在不必刷新整个浏览器的情况下，与服务器进行异步通讯的技术。</p><h2 id="xmlhttprequest" tabindex="-1">XMLHttpRequest <a class="header-anchor" href="#xmlhttprequest" aria-label="Permalink to &quot;XMLHttpRequest&quot;">​</a></h2><p>XMLHttpRequest对象是Ajax中最重要的一个对象。浏览器首先把请求发送到XMLHttpRequest异步对象中，异步对象对请求进行封装，然后再发送给服务器。服务器并不是以转发的形式回应，而是以流的方式把数据返回给浏览器。</p><p>下面介绍该对象的方法和属性。</p><h3 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h3><p><code>open(String method, String url, boolean asynch, String username, String password)</code></p><ul><li>method指定提交方式（post，get）</li><li>url指定请求发送的地址</li><li>asynch指定是异步还是同步，true表示异步，false表示同步</li><li>username, password是可选参数，在http认证时会用到。</li></ul><p><code>setRequestHeader(String header, String value)</code></p><ul><li>设置请求头部。</li></ul><p><code>send(content)</code></p><ul><li>发送请求给服务器。如果是get方式，不需要填参数；如果是post，要把提交的内容填上去。</li></ul><h3 id="属性" tabindex="-1">属性 <a class="header-anchor" href="#属性" aria-label="Permalink to &quot;属性&quot;">​</a></h3><ul><li><code>onreadystatechange</code>: 请求状态改变时的事件触发器（<code>readyState</code>变化时会调用此方法），一般用于指定回调函数。</li><li><code>readyState</code>：代表请求的状态，数字类型。有5个状态： <ul><li>0: 未初始化</li><li>1: open方法成功调用后</li><li>2: 服务器已经应答客户端的请求</li><li>3: 交互中。HTTP头部已经接受，响应数据尚未接受</li><li>4: 数据接收完成。</li></ul></li><li><code>responseText</code>: 服务器返回的文本内容。</li><li><code>responseXML</code>：服务器返回的兼容DOM的XML内容。</li><li><code>status</code>：服务器返回的状态码。</li><li><code>statusText</code>：服务器返回的状态码的文本信息。</li></ul>',14)])])}const x=a(i,[["render",r]]);export{h as __pageData,x as default};
